t=json.load(open('transkript.json',encoding='utf-8'))
GECER={'AA','BA','BB','CB','CC','DC','DD','B','A','C','D'}
seen={}
for d in t['dersler']:
    seen.setdefault(d['kod'],[]).append(d)
first_pass=[];retaken=[];failed_first=[]
for kod,lst in seen.items():
    f=lst[0]
    if f['not'] in GECER: first_pass.append(f)
    else: failed_first.append(f)
    if len(lst)>1: retaken.append((f['ad'],[x['not'] for x in lst]))
print('ilk denemede geçilen:',len(first_pass))
print('ilk denemede geçilemeyen:',[(f['ad'],f['not']) for f in failed_first])
print('tekrarlananlar:',retaken)
print('toplam farklı ders:',len(seen))
print('harfler:',sorted(set(d['not'] for d in t['dersler'] if d['not'])))
